<?php
require_once dirname(__DIR__) . '/app/views.php';
$q = substr(trim(is_string($_GET['q'] ?? null) ? $_GET['q'] : ''),0,100);
$category = is_string($_GET['category'] ?? null) ? $_GET['category'] : '';
$sort = is_string($_GET['sort'] ?? null) ? $_GET['sort'] : '';
$where = 'active=1'; $params = [];
if ($q !== '') { $where .= ' AND (title LIKE ? OR destination LIKE ?)'; $params[] = '%'.$q.'%'; $params[] = '%'.$q.'%'; }
if (in_array($category,['Nature','Culture','Beach','Wildlife'],true)) { $where .= ' AND category=?'; $params[] = $category; }
$order = ['price-asc'=>'price_cents ASC', 'price-desc'=>'price_cents DESC', 'duration'=>'duration_days ASC'][$sort] ?? 'id ASC';
$page = max(1,(int)($_GET['page'] ?? 1)); $count = (int)sql('SELECT COUNT(*) FROM tour_packages WHERE '.$where,$params)->fetchColumn(); $pages = max(1,(int)ceil($count/12)); $page = min($page,$pages); $offset = ($page-1)*12;
$packages = sql('SELECT * FROM tour_packages WHERE '.$where.' ORDER BY '.$order.' LIMIT 12 OFFSET '.$offset,$params)->fetchAll();
page_start('Our adventures','packages'); heading('FIND YOUR NEXT CHAPTER','A world of adventure, on one island.','Mountains, coastlines, culture and the unexpected. Make room for a little wonder.'); ?>
<section class="container pb-5"><form class="filter-bar" method="get"><div><label for="q" class="form-label">Search destinations</label><input class="form-control" id="q" name="q" value="<?= e($q) ?>" placeholder="Try Ella or Sigiriya" maxlength="100"></div><div><label class="form-label" for="category">Experience</label><select class="form-select" name="category" id="category"><?php foreach ([''=>'All experiences','Nature'=>'Nature','Culture'=>'Culture','Beach'=>'Beach','Wildlife'=>'Wildlife'] as $v=>$label): ?><option value="<?= e($v) ?>" <?= $category===$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div><label class="form-label" for="sort">Sort by</label><select class="form-select" name="sort" id="sort"><?php foreach ([''=>'Recommended','price-asc'=>'Price: low to high','price-desc'=>'Price: high to low','duration'=>'Shortest trips'] as $v=>$label): ?><option value="<?= e($v) ?>" <?= $sort===$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary" type="submit">Find adventures</button></form><p class="results-count"><?= $count ?> adventures to discover <a href="/packages.php">Reset filters</a></p><div class="row g-4"><?php foreach ($packages as $p): ?><div class="col-md-6 col-lg-4"><?php package_card($p); ?></div><?php endforeach; ?></div><?php if (!$packages): ?><div class="empty-state"><h2>No adventures found</h2><p>Try another destination or clear your filters.</p><a class="btn btn-primary" href="/packages.php">Explore all trips</a></div><?php endif; ?><?php if ($pages>1): ?><nav class="pagination-links mt-4" aria-label="Results pages"><?php for ($i=1;$i<=$pages;$i++): ?><a class="btn btn-outline-dark <?= $page===$i?'active':'' ?>" href="?<?= e(http_build_query(['q'=>$q,'category'=>$category,'sort'=>$sort,'page'=>$i])) ?>"><?= $i ?></a><?php endfor; ?></nav><?php endif; ?></section>
<?php page_end(); ?>
